edits.new:
const auto end = a.newLabel();

// Almost no opcode sits at a replaced position: test one byte of the filter table first, with no register save and no call.
// r15 is rewritten by the instruction at `end`, and pop does not change the flags of the cmp.
a.push(rax);
a.mov(rax, reinterpret_cast<std::uint64_t>(paris_vm_filter::table));
a.movzx(r15d, si);
a.cmp(byte_ptr(rax, r15), 0);
a.pop(rax);
a.je(end);

a.pushad64();

